-- Hand-written: full-audit invoicing fix (FX-4): a tax-only debit note is issued with no round-off, its total exactly its tax, generated by scripts/write-triggers.ts from src/triggers.ts.
CREATE TRIGGER `documents_tax_only_note_exact` BEFORE UPDATE OF status ON `documents` WHEN OLD.status = 'draft' AND NEW.status = 'issued' AND NEW.type = 'debit_note' AND NOT (NEW.type IS NOT 'debit_note' OR (json_extract(NEW.header_extras, '$.noteOf.reason.code') IS NOT 'tax_charged_too_low' AND NEW.taxable_minor IS NOT 0) OR (NEW.taxable_minor IS 0 AND NEW.round_off_minor IS 0 AND NEW.total_minor IS NEW.cgst_minor + NEW.sgst_minor + NEW.igst_minor AND coalesce(json_extract(NEW.computed, '$.inr.roundOffMinor'), 0) IS 0)) BEGIN SELECT RAISE(ABORT, 'documents_tax_only_note_exact: a tax-only debit note is issued with no round-off, its total exactly its tax'); END;
